import { z } from 'zod';
import { profileEvidence } from './profileEvidence';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import type {
  ProfileCandidate,
  ProfileRuntime,
} from '../../types/design-profile';
import {
  sourceIdsInFilter,
  type DesignLibraryMatch,
  type DesignLibraryReference,
} from '../../types/design-library';
import type { MemoryRuntime } from './MemoryRuntime';
import type { EngineBinding } from './MemoryModelService';
import { rankReferenceMatches } from './referenceSearchRanking';

const memory = z.object({
  id: z.string(),
  metadata: z
    .object({
      referenceId: z.string(),
      revision: z.number().int(),
      writeId: z.string(),
    })
    .passthrough(),
  isForgotten: z.boolean().optional(),
});
const searchHit = memory.extend({ similarity: z.number().finite() });
const listed = z.object({
  memoryEntries: z.array(memory),
  pagination: z.object({
    currentPage: z.number().int(),
    totalPages: z.number().int(),
  }),
});
const PAGE_SIZE = 100;
const CANDIDATE_LIMIT = 12;
const LIBRARY_SEARCH_LIMIT = 100;
const LIBRARY_MIN_SIMILARITY = 0.65;
const LIBRARY_SIMILARITY_WINDOW = 0.05;

export class ProfileIndex {
  private tail: Promise<unknown> = Promise.resolve();
  constructor(
    private readonly records: ProfileRecords,
    private readonly engine: MemoryRuntime,
  ) {}

  flush(runtime: ProfileRuntime, signal?: AbortSignal): Promise<void> {
    const run = this.tail
      .catch(() => undefined)
      .then(() => this.drain(runtime, signal));
    this.tail = run;
    return run;
  }

  async search({
    runtime,
    query,
    signal,
  }: {
    runtime: ProfileRuntime;
    query: string;
    signal?: AbortSignal;
  }): Promise<ProfileCandidate[]> {
    const candidates = this.records.candidates(
      (
        await this.searchEntries({
          runtime,
          query,
          limit: CANDIDATE_LIMIT,
          signal,
        })
      ).map((hit) => hit.metadata),
    );
    const unique = new Map(
      candidates.map((candidate) => [candidate.reference.id, candidate]),
    );
    return [...unique.values()];
  }

  async searchLibrary({
    runtime,
    query,
    sourceFilterId,
    signal,
    binding,
  }: {
    runtime: ProfileRuntime;
    query: string;
    sourceFilterId?: string;
    signal?: AbortSignal;
    binding?: EngineBinding;
  }): Promise<DesignLibraryMatch[]> {
    const hits = await this.searchEntries({
      runtime,
      query,
      limit: LIBRARY_SEARCH_LIMIT,
      minimumSimilarity: LIBRARY_MIN_SIMILARITY,
      signal,
      binding,
    });
    const references = new Map(
      this.filteredLibraryReferences(sourceFilterId).map((reference) => [
        reference.id,
        reference,
      ]),
    );
    const seen = new Set<string>();
    const ranked = hits.flatMap(({ metadata, similarity }) => {
      const reference = references.get(metadata.referenceId);
      if (
        !reference ||
        reference.revision !== metadata.revision ||
        seen.has(reference.id)
      )
        return [];
      seen.add(reference.id);
      return [{ reference, similarity }];
    });
    const bestSimilarity = ranked[0]?.similarity ?? 0;
    const minimumSimilarity = Math.max(
      LIBRARY_MIN_SIMILARITY,
      bestSimilarity - LIBRARY_SIMILARITY_WINDOW,
    );
    return this.rankLibraryMatches({
      query,
      references: [...references.values()],
      semanticMatches: ranked
        .filter(({ similarity }) => similarity >= minimumSimilarity)
        .map(({ reference }) => reference),
    });
  }

  searchSavedText({
    query,
    sourceFilterId,
  }: {
    query: string;
    sourceFilterId?: string;
  }): DesignLibraryMatch[] {
    return this.rankLibraryMatches({
      query,
      references: this.filteredLibraryReferences(sourceFilterId),
      semanticMatches: [],
    });
  }

  private filteredLibraryReferences(
    sourceFilterId?: string,
  ): DesignLibraryReference[] {
    const references = this.records.libraryReferences();
    if (!sourceFilterId) return references;
    const filteredSourceIds = sourceIdsInFilter({
      sources: this.records.sources(),
      filterId: sourceFilterId,
    });
    return references.filter((reference) =>
      reference.sourceIds.some((id) => filteredSourceIds.includes(id)),
    );
  }

  private rankLibraryMatches({
    query,
    references,
    semanticMatches,
  }: {
    query: string;
    references: DesignLibraryReference[];
    semanticMatches: DesignLibraryReference[];
  }): DesignLibraryMatch[] {
    const semanticIds = new Set(semanticMatches.map(({ id }) => id));
    return rankReferenceMatches({ query, semanticMatches, references }).map(
      (reference) => ({
        ...reference,
        matchedBy: semanticIds.has(reference.id) ? 'semantic' : 'saved_text',
      }),
    );
  }

  private async searchEntries({
    runtime,
    query,
    limit,
    minimumSimilarity = 0,
    signal,
    binding,
  }: {
    runtime: ProfileRuntime;
    query: string;
    limit: number;
    minimumSimilarity?: number;
    signal?: AbortSignal;
    binding?: EngineBinding;
  }): Promise<z.infer<typeof searchHit>[]> {
    const response = z.object({ results: z.array(searchHit) }).parse(
      await this.engine.request(
        runtime,
        '/v4/search',
        {
          q: query,
          containerTag: this.records.profile().id,
          searchMode: 'memories',
          limit,
          threshold: minimumSimilarity,
          rerank: false,
          aggregate: false,
          rewriteQuery: false,
        },
        'POST',
        signal,
        binding,
      ),
    );
    return response.results.filter((hit) => !hit.isForgotten);
  }

  private async entries(
    runtime: ProfileRuntime,
    signal?: AbortSignal,
  ): Promise<z.infer<typeof memory>[]> {
    const result: z.infer<typeof memory>[] = [];
    let page = 1;
    let totalPages = 1;
    do {
      const response = listed.parse(
        await this.engine.request(
          runtime,
          '/v4/memories/list',
          {
            containerTags: [this.records.profile().id],
            page,
            limit: PAGE_SIZE,
          },
          'POST',
          signal,
        ),
      );
      result.push(...response.memoryEntries);
      totalPages = response.pagination.totalPages;
      page += 1;
    } while (page <= totalPages);
    return result;
  }

  private async drain(
    runtime: ProfileRuntime,
    signal?: AbortSignal,
  ): Promise<void> {
    if (!this.records.pendingIndex(1).length) return;
    const entries = await this.entries(runtime, signal);
    const containerTag = this.records.profile().id;
    for (const work of this.records.pendingIndex()) {
      signal?.throwIfAborted();
      const existing = entries.filter(
        (entry) =>
          entry.metadata.referenceId === work.referenceId && !entry.isForgotten,
      );
      const matching = existing.find(
        (entry) => entry.metadata.writeId === work.id,
      );
      const obsolete = existing.filter(
        (entry) => work.operation === 'delete' || entry.id !== matching?.id,
      );
      for (const entry of obsolete)
        await this.engine.request(
          runtime,
          '/v4/memories',
          { containerTag, id: entry.id },
          'DELETE',
          signal,
        );
      if (work.operation === 'delete') {
        this.records.acknowledgeIndex({ ...work, engineId: null });
        continue;
      }
      const observation = this.records.observation(work.referenceId);
      const reference = this.records.reference(work.referenceId);
      if (!observation || !reference || observation.revision !== work.revision)
        continue;
      let engineId = matching?.id;
      if (!engineId) {
        const written = z
          .object({ memories: z.array(z.object({ id: z.string() })).length(1) })
          .parse(
            await this.engine.request(
              runtime,
              '/v4/memories',
              {
                containerTag,
                memories: [
                  {
                    content: profileEvidence(reference, observation),
                    isStatic: observation.evidence === 'preference',
                    metadata: {
                      referenceId: work.referenceId,
                      revision: work.revision,
                      writeId: work.id,
                    },
                  },
                ],
              },
              'POST',
              signal,
            ),
          );
        engineId = written.memories[0].id;
      }
      this.records.acknowledgeIndex({ ...work, engineId });
    }
  }
}
